/// <summary>
/// AVA/WEN 2024/03/27
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    SalesLine   lSalesLine;

    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(SalesOrderLineV2Entity, SalesLine):
            lSalesLine = _dataSourceCtx.getBuffer() as SalesLine;
            if (this.isFieldSet(fieldNum(SalesOrderLineV2Entity, SalesType)))
            {
                lSalesLine.SalesType = this.SalesType;
            }
            else
            {
                lSalesLine.SalesType = SalesType::Sales;
            }
            if (this.isFieldSet(fieldNum(SalesOrderLineV2Entity, AVAItemSet)))
            {
                lSalesLine.StockedProduct = !this.AVAItemSet;
            }

            break;
    }
}
